mapper.select:
SELECT s.name AS scene_name, COUNT(l.id) AS call_count, SUM(l.success) AS success_count, ROUND(AVG(l.latency_ms)) AS avg_latency FROM ai_call_log l LEFT JOIN ai_scene s ON l.scene_id = s.id
AND l.call_time >= #{startDate} AND l.call_time <= #{endDate}
GROUP BY l.scene_id, s.name ORDER BY call_count DESC
